create schema if not exists persona_data; revoke all on schema persona_data from public, anon, authenticated; create table persona_data.korean_personas (uuid text primary key check (uuid ~ '^[0-9a-f]{32}$'), age smallint not null check (age >= 19), age_group text not null, sex text not null, province text not null, district text, occupation text, marital_status text, family_type text, education_level text, persona text not null, details jsonb not null, sample_group text not null check (sample_group in ('base','supplement')), sample_reasons jsonb not null, source_revision text not null default 'ada0f5b53a38bb5a30cce09358adde883c1ab63a', sample_seed integer not null default 20261001); alter table persona_data.korean_personas enable row level security; revoke all on persona_data.korean_personas from public, anon, authenticated; create index korean_personas_demographics_idx on persona_data.korean_personas (age_group,sex,province); create index korean_personas_family_idx on persona_data.korean_personas (marital_status,family_type); create index korean_personas_occupation_idx on persona_data.korean_personas (occupation); comment on table persona_data.korean_personas is 'NVIDIA Nemotron-Personas-Korea CC BY 4.0 합성 데이터. 4만 분포 표본+1만 다양성 보충. 실제 여론 대표 표본 아님.';
